import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry sigmoid_kernel_vec4(
    .param .u64 sigmoid_kernel_vec4_param_0,
    .param .u64 sigmoid_kernel_vec4_param_1,
    .param .u64 sigmoid_kernel_vec4_param_2
)
{
    .reg .pred %p<3>;
    .reg .f32 %f<20>;
    .reg .b32 %r<8>;
    .reg .b64 %rd<20>;

    ld.param.u64 %rd1, [sigmoid_kernel_vec4_param_0];
    ld.param.u64 %rd2, [sigmoid_kernel_vec4_param_1];
    ld.param.u64 %rd3, [sigmoid_kernel_vec4_param_2];
    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;

    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mov.u32 %r4, %nctaid.x;

    cvt.u64.u32 %rd6, %r1;
    cvt.u64.u32 %rd7, %r2;
    cvt.u64.u32 %rd8, %r3;
    cvt.u64.u32 %rd9, %r4;

    mul.lo.s64 %rd10, %rd6, %rd7;
    add.s64 %rd11, %rd10, %rd8;
    mul.lo.s64 %rd12, %rd9, %rd7;

$L_loop_start:
    setp.ge.s64 %p1, %rd11, %rd3;
    @%p1 bra $L_loop_end;

    shl.b64 %rd13, %rd11, 4;
    add.s64 %rd14, %rd4, %rd13;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd14];

    mov.f32 %f10, 0f3FB8AA3B;
    mov.f32 %f11, 0f3F800000;

    neg.f32 %f12, %f1;
    mul.f32 %f13, %f12, %f10;
    ex2.approx.f32 %f14, %f13;
    add.f32 %f15, %f14, %f11;
    rcp.rn.f32 %f5, %f15;

    neg.f32 %f16, %f2;
    mul.f32 %f17, %f16, %f10;
    ex2.approx.f32 %f18, %f17;
    add.f32 %f19, %f18, %f11;
    rcp.rn.f32 %f6, %f19;

    neg.f32 %f12, %f3;
    mul.f32 %f13, %f12, %f10;
    ex2.approx.f32 %f14, %f13;
    add.f32 %f15, %f14, %f11;
    rcp.rn.f32 %f7, %f15;

    neg.f32 %f16, %f4;
    mul.f32 %f17, %f16, %f10;
    ex2.approx.f32 %f18, %f17;
    add.f32 %f19, %f18, %f11;
    rcp.rn.f32 %f8, %f19;

    add.s64 %rd15, %rd5, %rd13;
    st.global.v4.f32 [%rd15], {%f5, %f6, %f7, %f8};

    add.s64 %rd11, %rd11, %rd12;
    bra.uni $L_loop_start;

$L_loop_end:
    ret;
}

.visible .entry sigmoid_kernel_scalar(
    .param .u64 sigmoid_kernel_scalar_param_0,
    .param .u64 sigmoid_kernel_scalar_param_1,
    .param .u64 sigmoid_kernel_scalar_param_2,
    .param .u64 sigmoid_kernel_scalar_param_3
)
{
    .reg .pred %p<2>;
    .reg .f32 %f<8>;
    .reg .b32 %r<5>;
    .reg .b64 %rd<14>;

    ld.param.u64 %rd1, [sigmoid_kernel_scalar_param_0];
    ld.param.u64 %rd2, [sigmoid_kernel_scalar_param_1];
    ld.param.u64 %rd3, [sigmoid_kernel_scalar_param_2];
    ld.param.u64 %rd4, [sigmoid_kernel_scalar_param_3];

    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;

    cvt.u64.u32 %rd5, %r1;
    cvt.u64.u32 %rd6, %r2;
    cvt.u64.u32 %rd7, %r3;

    mul.lo.s64 %rd8, %rd5, %rd6;
    add.s64 %rd9, %rd8, %rd7;
    add.s64 %rd10, %rd9, %rd3;

    setp.ge.s64 %p1, %rd10, %rd4;
    @%p1 bra $L_scalar_end;

    cvta.to.global.u64 %rd11, %rd1;
    shl.b64 %rd12, %rd10, 2;
    add.s64 %rd13, %rd11, %rd12;
    ld.global.f32 %f1, [%rd13];

    mov.f32 %f2, 0f3FB8AA3B;
    mov.f32 %f3, 0f3F800000;

    neg.f32 %f4, %f1;
    mul.f32 %f5, %f4, %f2;
    ex2.approx.f32 %f6, %f5;
    add.f32 %f7, %f6, %f3;
    rcp.rn.f32 %f1, %f7;

    cvta.to.global.u64 %rd11, %rd2;
    add.s64 %rd13, %rd11, %rd12;
    st.global.f32 [%rd13], %f1;

$L_scalar_end:
    ret;
}
"""

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    module = _get_module()
    fn_vec4 = module.function("sigmoid_kernel_vec4")
    fn_scalar = module.function("sigmoid_kernel_scalar")
    assert fn_vec4 is not None
    assert fn_scalar is not None
    return True


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a hand-written
    PTX kernel executed via cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self):
        super(ModelNew, self).__init__()
        self._module = None
        self._sm_count = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        if self._module is None:
            self._module = _get_module()

        if self._sm_count is None:
            try:
                props = torch.cuda.get_device_properties(x.device)
                self._sm_count = int(props.multi_processor_count)
            except Exception:
                self._sm_count = 0

        x_c = x.contiguous()
        y = torch.empty_like(x_c)

        N = x_c.numel()
        N4 = N // 4
        rem_start = N4 * 4
        rem = N - rem_start

        in_ptr = x_c.data_ptr()
        out_ptr = y.data_ptr()

        stream = torch.cuda.current_stream().cuda_stream

        if N4 > 0:
            threads = 256
            blocks64 = (N4 + threads - 1) // threads
            max_blocks = 65535

            # Occupancy tuning: align the launched grid size to a multiple of
            # the device's SM count so that every "wave" of CTAs scheduled on
            # the GPU is fully populated. Previously the grid was simply
            # capped at max_blocks, which (for large N4) is not a multiple of
            # the SM count and results in a partially-filled final wave,
            # lowering achieved occupancy despite a grid-stride loop covering
            # all elements. This keeps the exact same kernel semantics.
            sm_count = self._sm_count
            if sm_count and sm_count > 0:
                blocks_per_sm = max_blocks // sm_count
                if blocks_per_sm < 1:
                    blocks_per_sm = 1
                aligned_max_blocks = sm_count * blocks_per_sm
            else:
                aligned_max_blocks = max_blocks

            blocks = int(min(blocks64, aligned_max_blocks))
            if blocks < 1:
                blocks = 1

            self._module.launch(
                "sigmoid_kernel_vec4",
                grid=(blocks, 1, 1),
                block=(threads, 1, 1),
                stream=stream,
                args=[u64(in_ptr), u64(out_ptr), i64(N4)],
            )

        if rem > 0:
            threads = 128
            blocks = int((rem + threads - 1) // threads)
            if blocks < 1:
                blocks = 1

            self._module.launch(
                "sigmoid_kernel_scalar",
                grid=(blocks, 1, 1),
                block=(threads, 1, 1),
                stream=stream,
                args=[u64(in_ptr), u64(out_ptr), i64(rem_start), i64(N)],
            )

        return y.view(x.sizes())

