#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Vectorized sigmoid kernel operating on float4 chunks using CuTe tensors
__global__ void sigmoid_kernel_vec4(const float4* __restrict__ in,
                                     float4* __restrict__ out,
                                     int64_t N4)
{
  Tensor mX = make_tensor(make_gmem_ptr(in),  make_shape(N4));
  Tensor mY = make_tensor(make_gmem_ptr(out), make_shape(N4));

  int64_t idx4    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride4 = (int64_t)gridDim.x * blockDim.x;

  for (; idx4 < N4; idx4 += stride4) {
    float4 v = mX(idx4);
    float4 r;
    r.x = 1.0f / (1.0f + expf(-v.x));
    r.y = 1.0f / (1.0f + expf(-v.y));
    r.z = 1.0f / (1.0f + expf(-v.z));
    r.w = 1.0f / (1.0f + expf(-v.w));
    mY(idx4) = r;
  }
}

// Scalar remainder kernel using CuTe tensors for any leftover elements
__global__ void sigmoid_kernel_scalar(const float* __restrict__ in,
                                       float* __restrict__ out,
                                       int64_t start,
                                       int64_t N)
{
  Tensor mX = make_tensor(make_gmem_ptr(in),  make_shape(N));
  Tensor mY = make_tensor(make_gmem_ptr(out), make_shape(N));

  int64_t idx = start + (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  if (idx < N) {
    float x = mX(idx);
    mY(idx) = 1.0f / (1.0f + expf(-x));
  }
}

torch::Tensor cute_sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y   = torch::empty_like(x_c);

  int64_t N  = x_c.numel();
  int64_t N4 = N / 4;
  int64_t rem_start = N4 * 4;
  int64_t rem = N - rem_start;

  const float* in_ptr  = x_c.data_ptr<float>();
  float*       out_ptr = y.data_ptr<float>();

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (N4 > 0) {
    const int threads = 256;
    int64_t blocks64 = (N4 + threads - 1) / threads;
    // cap grid size to a reasonable value; grid-stride loop handles the rest
    int64_t max_blocks = 65535;
    int blocks = (int)(blocks64 < max_blocks ? blocks64 : max_blocks);
    if (blocks < 1) blocks = 1;

